      "start_block": "B006",
      "end_block": "B014",
      "hook": "A guard in black uniform pauses outside a dungeon cell, glancing nervously over his shoulder to ensure he is unobserved.",
      "cliffhanger": "The guard urgently whispers 'Eat it before they see' as he prepares to leave.",
      "why": "Immediate visual tension of a forbidden act combined with the high stakes of starvation and discovery creates instant intrigue.",
      "context_gap": "None; the viewer sees a prisoner being secretly fed by a guard, implying danger."
    },
    {
      "title": "Juliana's Defiant Vow",
      "start_block": "B038",
      "end_block": "B042",
      "hook": "Juliana, trembling but resolute, declares she will not give her husband to the enemy despite her impending death.",
      "cliffhanger": "Her eyes snap wide open in sudden realization just as a deep resonant toll reverberates from above.",
      "why": "Shifts from emotional despair to fierce defiance, ending on a sharp auditory shock that signals a major event.",
      "context_gap": "None; the viewer understands she is protecting her husband against those who want her dead."
    },
    {
      "title": "Wedding Bells and Death Knell",
      "start_block": "B043",
      "end_block": "B055",
      "hook": "Juliana's eyes snap wide open as solemn church bells begin tolling rhythmically from the cathedral above.",
      "cliffhanger": "Juliana grips the bars with a warm, defiant smile and whispers 'Alexander...' right before the screen cuts to black.",
      "why": "Connects the sound of a wedding to her execution decree, creating a terrifying irony and ending on a hopeful yet unresolved note.",
      "context_gap": "None; the viewer understands the bells signal the start of Rupert's wedding and her execution."
    }
  ],
  "moments": [
    {
      "start_block": "B009",
      "end_block": "B011",
