      "description": "Starving Juliana tears off a desperate bite of bread and weeps for Alexander."
    },
    {
      "start_block": "B043",
      "end_block": "B047",
      "kind": "reveal",
      "description": "Juliana realizes the tolling bells mean Rupert's wedding has begun."
    },
    {
      "start_block": "B053",
      "end_block": "B055",
      "kind": "cliffhanger",
      "description": "Juliana smiles defiantly at the bars and whispers her husband's name as the scene cuts."
